//let fragSource;

function preload()
{
	  vertSource = loadStrings('https://openprocessing.org/sketch/1862927/files/default.vert');
		fragSource = loadStrings('https://openprocessing.org/sketch/1862927/files/waves.frag');
}

function setup() {
	pixelDensity(1);
	createCanvas(1112,834,WEBGL);
	vertSource = resolveLygia(vertSource);
  fragSource = resolveLygia(fragSource);
	shdr = createShader(vertSource, fragSource);
}

function draw() {
	shader(shdr);

  shdr.setUniform('u_resolution', [width, height] );
  shdr.setUniform('u_mouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
  shdr.setUniform('u_time', millis() / 1000.0);

  rect(0,0, width, height);
}

// === Tab: waves.frag ===
#ifdef GL_ES
precision mediump float;
#endif

uniform float       u_time;
uniform vec2        u_resolution;

// using the lygia library https://github.com/patriciogonzalezvivo/lygia

#include "lygia/space/ratio.glsl"
#include "lygia/sdf/lineSDF.glsl"
#include "lygia/generative/snoise.glsl"
#include "lygia/math/smootherstep.glsl"

vec3 colorPalette(int i)
{
  if (i == 0)
  {
   return vec3(0.949,0.922,0.541);
  }else if (i==1)
  {
    return vec3(0.996,0.816,0.);
  }else if (i==2)
  {
    return vec3(0.988,0.518,0.0);
  }else if (i==3)
  {
   return vec3(0.929,0.212,0.102);
  }else if (i==4)
  {
   return  vec3(0.886,0.941,0.953);
  }else if (i==5)
  {
   return vec3(0.702,0.863,0.878);
  }else if (i==6)
  {
   return vec3(0.267,0.392,0.631);
  }else if (i==7)
  {
    return vec3(0.125,0.188,0.318);
  }else if (i==8)
  {
    return vec3(1.,0.773,0.78);
  }else if (i==9)
  {
    return vec3(0.953,0.596,0.765);
  }else if (i==10)
  {
   return vec3(0.812,0.22,0.584);
  }else if (i==11)
  {
   return vec3(0.427,0.208,0.541);
  }else if (i==12)
  {
    return vec3(0.024,0.706,0.69);
  }else 
  {
    return vec3(0.294,0.541,0.373);
  }
}


void main() {

    vec2 st = gl_FragCoord.xy/u_resolution.xy;
    st = ratio(st, u_resolution)-0.5; 

    vec3 color = vec3(0.0);

    st *= 0.4;

    for(int i=0;i < 14;i++)
    {
      float w = 0.3;

      float freq;

      if (float(mod(float(i),2.0)) == 0.0)
      {
        freq = 0.0;
      }else
      {
        freq = 0.1;
      }

      float ruido = snoise(st*5.0 + freq*u_time - 5.0*float(i));

      color = mix(colorPalette(i)+ ruido,color,smootherstep(w - 0.025,w + 0.025,lineSDF(st+ruido,vec2(0.,-0.5),vec2(0.0,0.5))));
    }

    gl_FragColor = vec4(color,1.0);
}

